+    '',
+    '## Boundary',
+    '',
+    '- The packet is not a SourceFigureAsset acceptance decision.',
+    '- The packet is not a rights, SourceVisualReceipt, QuestionRenderModel, Method Map, ProcedureModel, ProcedureStep, scoring, or mark-scheme truth decision.',
+    '- Historical crops and existing image refs are auxiliary evidence pointers only.',
+    '- The first shard is selected by the usage-prioritized route and deterministic `usage_priority_seed` proxy because no real usage signal is present in the source artifacts.',
+    '',
+    '## Shards',
+    '',
+    `- ${SHARD_ID}: ${packet.shard.selected_row_count} selected rows, ${packet.summary.backlog_row_count} backlog rows.`,
+  ].join('\n');
+}
+
+function buildReadback({ packet, validatorResult, output }) {
+  return [
+    '# FigureAsset VLM Candidate Packet Shard 000 Readback',
+    '',
+    `Generated: ${packet.generated_at}`,
+    '',
+    '## Shard',
+    '',
+    `- Selected rows: ${packet.shard.selected_row_count}`,
+    `- Backlog rows: ${packet.summary.backlog_row_count}`,
