+    '- `vlm_not_run` is encoded because this worker has no explicit external VLM authorization.',
+    '',
+    '## Validation',
+    '',
+    `- Status: ${validatorResult.summary.validation_status}`,
+    `- Checks: ${validatorResult.summary.check_count}`,
+    `- Failed checks: ${validatorResult.summary.failed_check_count}`,
+  ].join('\n');
+}
+
+function serializedJson(value) {
+  return `${JSON.stringify(value, null, 2)}\n`;
+}
+
+function existingFile(root, relPath) {
+  const target = path.join(root, relPath);
+  if (!fs.existsSync(target)) return null;
+  return fs.readFileSync(target, 'utf8').replace(/\r\n/g, '\n');
+}
+
+function generatedArtifacts(paths, result) {
+  const artifacts = [
+    ['readme', paths.readmeOut, result.readme.endsWith('\n') ? result.readme : `${result.readme}\n`],
+    ['input_packet', paths.shardInputOut, serializedJson(result.packet)],
+    ['validator_result', paths.validatorOut, serializedJson(result.validatorResult)],
+    ['readback', paths.readbackOut, result.readback.endsWith('\n') ? result.readback : `${result.readback}\n`],
+  ];
+  if (result.output) {
+    artifacts.push(['output_packet', paths.shardOutputOut, serializedJson(result.output)]);
+  }
+  return artifacts;
+}
+
+function compareGeneratedArtifacts(root, paths, result) {
+  return generatedArtifacts(paths, result).map(([role, relPath, content]) => {
+    const existing = existingFile(root, relPath);
+    return {
+      role,
+      path: relPath,
+      exists: existing !== null,
+      matches_generated: existing === content,
+    };
+  });
+}
+
+function writeGeneratedArtifacts(root, paths, result) {
+  for (const [role, relPath, content] of generatedArtifacts(paths, result)) {
+    if (role.endsWith('packet') || role === 'validator_result') {
+      writeJson(root, relPath, JSON.parse(content));
+    } else {
+      writeText(root, relPath, content);
+    }
+  }
+}
+
+function loadInputs(root, paths, diagnostics = []) {
+  return {
+    visualInventory: safeReadJson(root, paths.visualInventoryIn, 'full_beta_visual_required_inventory', diagnostics) ?? { rows: [] },
+    rightsOverlay: safeReadJson(root, paths.rightsOverlayIn, 'source_figure_asset_rights_display_policy', diagnostics) ?? null,
+  };
+}
+
+export function buildFigureAssetVlmCandidatePacketShard(options = {}) {
+  const root = options.root ?? repoRootFromScript();
+  const paths = { ...DEFAULT_PATHS, ...(options.paths ?? {}) };
+  const generatedAt = options.generatedAt ?? DEFAULT_GENERATED_AT;
+  const shardSize = options.shardSize ?? DEFAULT_SHARD_SIZE;
+  const diagnostics = [...asArray(options.diagnostics)];
+  const inputs = options.inputs ?? loadInputs(root, paths, diagnostics);
+  const rawRows = visualInventoryRows(inputs.visualInventory, paths, diagnostics);
+  const rows = validVisualRows(rawRows, diagnostics);

